/// `ar` as CLDR 48 resolves it, with its overrides.
pub(super) const AR: LocaleData = LocaleData {
    tag: "ar",
    long: AR_LONG,
    short: AR_SHORT,
    narrow: AR_NARROW,
    compact: UnitStrings::EMPTY,
    indefinite: UnitStrings::EMPTY,
    list: ListPatterns {
        standard: ListForms {
            two: "{0} و{1}",
            start: "{0} و{1}",
            middle: "{0} و{1}",
            end: "{0} و{1}",
        },
        unit: ListForms {
            two: "{0} و{1}",
            start: "{0}، و{1}",
            middle: "{0}، و{1}",
            end: "{0}، و{1}",
        },
        narrow: ListForms {
            two: "{0} و{1}",
            start: "{0} و{1}",
            middle: "{0} و{1}",
            end: "{0} و{1}",
        },
    },
    approximate: LANGUAGE_FREE_HEDGES,
    weekday: LANGUAGE_FREE_WEEKDAYS,
    decimal_separator: "٫",
    at_pattern: "{0} في {1}",
};

